<?php

/**
 * Default settings for the Static Maps API.
 *
 * DO NOT EDIT THIS FILE to change settings on your install: it is part of the
 * code and will be overwritten when you update. Instead, copy
 * `data/config.example.php` to `data/config.php` and put only the settings you
 * want to change there. Your file is merged over this one:
 *
 * - Settings that are arrays with named keys (such as `defaults`, `zoom`,
 *   `basemaps` and each individual basemap) are merged key by key, so you only
 *   list the keys you change.
 * - Everything else, including lists such as a basemap's `layers`, is replaced
 *   as a whole.
 *
 * A different install file can be used by setting the STATIC_MAPS_CONFIG
 * environment variable to its full path (for example in the PHP-FPM pool
 * configuration, or in tests).
 *
 * @see data/config.example.php
 */

return [

    /*
     * Values used when a request does not specify them.
     */
    'defaults' => [
        // Image width and height in pixels when the request has no `width` / `height`.
        // Default: 300 x 300.
        // Example override: 'defaults' => ['width' => 600, 'height' => 400],
        'width'        => 300,
        'height'       => 300,

        // Path line colour (hex RGB without '#') and weight (pixels) when a
        // `path[]` or `polyline` does not set `color:` / `weight:`.
        // Default: '333333' and 3.
        'path_color'   => '333333',
        'path_weight'  => 3,

        // Output format when the request has no `format`: 'png' or 'jpg'.
        // Default: 'png'.
        'format'       => 'png',

        // JPEG quality (0-100) when `format=jpg` and the request has no `quality`.
        // Default: 75.
        'jpeg_quality' => 75,

        // Basemap used when the request has no `basemap`, names an unknown or
        // disabled basemap, or names one that needs a token it doesn't have.
        // Must be the id of an enabled entry in `basemaps` below.
        // Default: 'osm'.
        'basemap'      => 'osm',

        // Attribution drawn when the request has no `attribution` and the
        // basemap has no `attribution` of its own. One of 'osm', 'esri' or
        // 'mapbox' (any other value currently draws the OSM logo, see #18).
        // Default: 'osm'.
        'attribution'  => 'osm',
    ],

    /*
     * Zoom limits for every basemap. A basemap can narrow these with its own
     * `minzoom` / `maxzoom`. Requested or automatically chosen zoom levels
     * outside the range are clamped to it.
     * Default: 2 to 18.
     * Example override: 'zoom' => ['max' => 17],
     */
    'zoom' => [
        'min' => 2,
        'max' => 18,
    ],

    /*
     * User-Agent header sent when downloading tiles. Tile providers such as
     * OpenStreetMap require a User-Agent that identifies the application.
     * Set this to something that identifies your install, for example
     * 'Static Maps API/ maps.example.com (admin@example.com)'.
     */
    'user_agent' => 'Static Maps API/ github.com/dshanske/Static-Maps-API-PHP',

    /*
     * File with the access tokens, one per line. A request whose `token`
     * parameter matches a line may use external marker icon URLs,
     * `basemap=custom` with `tileurl`, and basemaps with `requires_auth`.
     * If the file doesn't exist, no token is valid.
     * Default: data/apikeys.txt.
     * Example override: 'token_file' => '/etc/static-maps/tokens.txt',
     */
    'token_file' => __DIR__ . '/../data/apikeys.txt',

    /*
     * HTML page returned for a request without any parameters, for example
     * when someone opens the service's address in a browser. The file is sent
